"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["86622"],{31811(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.estrutura_formulario.dado_basico_alterado","status":422,"titulo":"O item do conjunto b\xe1sico de dados do candidato n\xe3o pode ser alterado"},"descricao":{"codigo":"uniplus.estrutura_formulario.dado_basico_alterado","requisitos":["UNI-REQ-0151"],"oQueAconteceu":["Todo formul\xe1rio de inscri\xe7\xe3o coleta o conjunto b\xe1sico de dados do candidato (UNI-REQ-0151) numa se\xe7\xe3o reservada, a primeira do formul\xe1rio, e o conjunto \xe9 o mesmo em todo processo e em todo modelo de formul\xe1rio de inscri\xe7\xe3o. Por isso, o item do conjunto que vem no pedido pode ser repetido como est\xe1, ou omitido, e o sistema o rep\xf5e; ele n\xe3o pode ser alterado. A recusa sai quando o item b\xe1sico enviado difere do item do conjunto em qualquer elemento que n\xe3o seja a ordem e o r\xf3tulo, que s\xe3o do conjunto, como a obrigatoriedade, a exibi\xe7\xe3o, as restri\xe7\xf5es, a ajuda ou a se\xe7\xe3o; uma condi\xe7\xe3o sem valor tamb\xe9m o torna diferente. A mensagem \xe9 \\"O item \'`{fato\\\\}`\' \xe9 do conjunto b\xe1sico de dados do candidato: pode ser repetido como est\xe1, ou omitido, mas n\xe3o alterado.\\", com o c\xf3digo do fato do conjunto.","A recusa vem na lista `errors` da resposta, com `field` igual a `itens[i]`, uma entrada por item alterado; nos modelos de formul\xe1rio o `field` come\xe7a por `conteudo.`. Nada \xe9 gravado. A confer\xeancia vale s\xf3 para o formul\xe1rio de inscri\xe7\xe3o e o modelo que serve \xe0 fase de inscri\xe7\xe3o; nos demais o conjunto n\xe3o existe.","O item do conjunto que o pedido omite \xe9 reposto pelo sistema, com a ordem e o r\xf3tulo do conjunto. Nos modelos de formul\xe1rio, a confer\xeancia s\xf3 ocorre quando o conte\xfado foi lido sem recusa de leitura (como a de [conte\xfado malformado](/erros/uniplus.configuracao.modelo_formulario.entrada_malformada)), e na atualiza\xe7\xe3o um `{id}` que n\xe3o existe \xe9 recusado antes, como [modelo de formul\xe1rio n\xe3o encontrado](/erros/uniplus.configuracao.modelo_formulario.nao_encontrado)."],"comoResolver":["Retire do pedido o item do conjunto b\xe1sico que foi alterado, ou envie-o exatamente como o formul\xe1rio o tem: o sistema usa o item do conjunto, com a ordem e o r\xf3tulo dele. Se a necessidade \xe9 outra pergunta al\xe9m das do conjunto, acrescente-a como item pr\xf3prio, fora da se\xe7\xe3o reservada."],"ondeAparece":["Cria\xe7\xe3o de um modelo de formul\xe1rio","Atualiza\xe7\xe3o de um modelo de formul\xe1rio","Grava\xe7\xe3o dos itens do formul\xe1rio"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Estrutura formulario"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3bbcc2307827ee8c6dab135295710bb856847f61"}}')}}]);